//! Native cloned boundaries retain the canonical active method realm.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=root>A😀B</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://range-clone.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,Main=Range,Child=w.Range,mainClone=Main.prototype.cloneRange,childClone=Child.prototype.cloneRange,root=document.getElementById('root'),text=root.firstChild,r=document.createRange();r.setStart(text,1);r.setEnd(text,3);");(d,f,p)}
#[test]
fn range_clone_realm_borrowed_methods_choose_canonical_callee_across_native_owners(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var copied=childClone.call(r);if(copied===r||Object.getPrototypeOf(copied)!==Child.prototype||copied instanceof Main||copied.startContainer!==text||copied.endContainer!==text||copied.startOffset!==1||copied.endOffset!==3||copied.toString()!=='😀')throw 'callee realm independent of main native receiver';var reverse=mainClone.call(copied);if(Object.getPrototypeOf(reverse)!==Main.prototype||reverse instanceof Child||reverse.startContainer!==text||reverse.toString()!=='😀')throw 'reverse borrowed main method realm';var child=new Child();child.selectNodeContents(w.document.documentElement);var fromChild=mainClone.call(child);if(Object.getPrototypeOf(fromChild)!==Main.prototype||fromChild.startContainer!==w.document.documentElement||fromChild.endOffset!==2)throw 'child endpoints independent of clone method realm';
var owner=new Document(),leaf=owner.createTextNode('\uD800A\uDC00'),inert=owner.createRange();inert.setStart(leaf,1);inert.setEnd(leaf,3);var native=Child.prototype;w.Function('Range=function(){};')();var another=childClone.call(inert);if(Object.getPrototypeOf(another)!==native||another.startContainer!==leaf||another.toString().charCodeAt(1)!==56320)throw 'canonical saved clone after shadow with inert endpoints';var attr=owner.createAttribute('x');inert.selectNodeContents(attr);var attrCopy=childClone.call(inert);if(attrCopy.startContainer!==attr||!attrCopy.collapsed||Object.getPrototypeOf(attrCopy)!==native)throw 'actual Attr root with canonical method realm';
"#);}
#[test]
fn range_clone_realm_live_state_exact_stringifier_and_legacy_detach_are_independent(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var copy=childClone.call(r),fixed=new StaticRange({startContainer:text,startOffset:1,endContainer:text,endOffset:3});r.collapse(false);if(r.toString()!==''||copy.toString()!=='😀'||copy.collapsed||copy.detach()!==undefined||copy.toString()!=='😀')throw 'independent live clone and legacy no-op';text.insertData(1,'X');if(copy.startOffset!==1||copy.endOffset!==4||copy.toString()!=='X😀'||r.startOffset!==4||fixed.endOffset!==3)throw 'both actual live records participate in native splice';var owner=new Document(),fragment=owner.createDocumentFragment();fragment.appendChild(owner.createTextNode('A'));fragment.appendChild(owner.createComment('hidden'));fragment.appendChild(owner.createProcessingInstruction('target','hidden'));fragment.appendChild(owner.createCDATASection('😀B'));var selected=owner.createRange();selected.selectNodeContents(fragment);var exact=childClone.call(selected);selected.collapse(true);if(exact.toString()!=='A😀B'||exact.endOffset!==4||exact.startContainer!==fragment||Object.getPrototypeOf(exact)!==Child.prototype)throw 'native clone stringifier skips nontext and includes CDATA exact units';
"#);}
#[test]
fn range_clone_realm_brands_origin_and_disconnection_refuse_without_native_publication(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var caught=0;for(var value of [{},root,new StaticRange({startContainer:text,startOffset:1,endContainer:text,endOffset:3})]){try{childClone.call(value);}catch(e){if(e instanceof w.TypeError)caught++;}}if(caught!==3)throw 'native live Range brand in method realm';var endpoint=document.createRange();endpoint.selectNodeContents(w.document.documentElement);");let before=(p.state.ranges.len(),p.state.retained,p.state.dom_commits);
 p.set_location(&crate::navigation::address("https://foreign.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();for source in ["childClone.call(r)","mainClone.call(endpoint)"]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.ranges.len(),p.state.retained,p.state.dom_commits),before);}
 p.set_location(&crate::navigation::address("https://range-clone.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"var fresh=childClone.call(r);if(Object.getPrototypeOf(fresh)!==Child.prototype||fresh.toString()!=='😀')throw 'fresh clone authority recovery';frame.parentNode.removeChild(frame);");let before=(p.state.ranges.len(),p.state.dom_commits);p.begin_job();assert!(p.runtime.execute("childClone.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.ranges.len(),p.state.dom_commits),before);run(&mut d,&mut f,&mut p,"var restored=mainClone.call(r);if(Object.getPrototypeOf(restored)!==Main.prototype||restored.toString()!=='😀')throw 'main clone recovery after foreign method disconnection';");
}
#[test]
fn range_clone_realm_checked_record_growth_refusal_preserves_source_and_recovers(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();p.begin_job();{let mut b=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};while b.state.ranges.len()<b.state.ranges.capacity(){b.create_range(WINDOW,DOCUMENT).unwrap();}}let before=(p.state.ranges.len(),p.state.ranges.capacity(),p.state.retained,p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end);let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>{p.state.host_work=4096;p.state.execution_deadline=Some(Instant::now());}}assert!(p.runtime.execute("childClone.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.ranges.len(),p.state.ranges.capacity(),p.state.retained,p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end),before);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"var recovered=childClone.call(r);if(recovered.startContainer!==text||recovered.startOffset!==1||recovered.endOffset!==3||recovered.toString()!=='😀'||Object.getPrototypeOf(recovered)!==Child.prototype||r.toString()!=='😀')throw 'fresh checked canonical clone recovery';");assert_eq!(p.state.ranges.len(),before.0+1);assert_eq!(p.state.retained-before.2,(p.state.ranges.capacity()-before.1)*std::mem::size_of::<script_ranges::Record>());}
}
